using System.Security.Claims;
using AeppGenerator.Api.Data;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
namespace AeppGenerator.Api.Auth;
public static class AuthSetup {
 public static void AddAccounts(this WebApplicationBuilder builder){var store=new AccountStore(builder.Configuration["Accounts:DatabasePath"]??Path.Combine(builder.Environment.ContentRootPath,"App_Data","accounts.sqlite"));var auth=new AuthService(store,builder.Configuration,builder.Environment);builder.Services.AddSingleton(store);builder.Services.AddSingleton(auth);builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(options=>{options.MapInboundClaims=false;options.TokenValidationParameters=new(){ValidateIssuer=true,ValidIssuer=auth.Issuer,ValidateAudience=true,ValidAudience=auth.Audience,ValidateLifetime=true,RequireExpirationTime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(auth.Key),ValidAlgorithms=[SecurityAlgorithms.HmacSha256],ClockSkew=TimeSpan.FromSeconds(15),NameClaimType="name",RoleClaimType="role"};options.Events=new JwtBearerEvents{OnMessageReceived=context=>{if(!context.Request.Headers.ContainsKey("Authorization")&&context.Request.Cookies.TryGetValue(AuthService.CookieName,out var token))context.Token=token;return Task.CompletedTask;},OnTokenValidated=context=>{var user=context.Principal!;if(!store.ValidSession(user.FindFirstValue("jti")??"",user.FindFirstValue("sub")??"",user.FindFirstValue("role")??""))context.Fail("Η συνεδρία έληξε.");return Task.CompletedTask;},OnChallenge=async context=>{context.HandleResponse();context.Response.StatusCode=401;await context.Response.WriteAsJsonAsync(new{message="Χρειάζεται σύνδεση ή η συνεδρία σου έχει λήξει."});},OnForbidden=async context=>{context.Response.StatusCode=403;await context.Response.WriteAsJsonAsync(new{message="Δεν έχεις δικαίωμα για αυτή την ενέργεια."});}};});builder.Services.AddAuthorization();}
 public static void UseAccountOriginGuard(this WebApplication app){var allowed=(app.Configuration["Auth:FrontendOrigins"]??"http://localhost:5173,http://127.0.0.1:5173").Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);app.Use(async(context,next)=>{if(context.Request.Path.StartsWithSegments("/api")&&!HttpMethods.IsGet(context.Request.Method)&&!HttpMethods.IsHead(context.Request.Method)&&!HttpMethods.IsOptions(context.Request.Method)&&context.Request.Cookies.ContainsKey(AuthService.CookieName)&&!context.Request.Headers.ContainsKey("Authorization")){var origin=context.Request.Headers.Origin.ToString();var self=context.Request.Scheme+"://"+context.Request.Host;if(origin!=self&&!allowed.Contains(origin,StringComparer.Ordinal)){context.Response.StatusCode=403;await context.Response.WriteAsJsonAsync(new{message="Η προέλευση του αιτήματος δεν επιτρέπεται."});return;}}await next();});}
}
